-- =====================================================================================================
--  BillPoodum — Turso (libSQL / SQLite) schema: shop database (one per shop)
-- =====================================================================================================
--  GENERATED by backend/scripts/gen-sqlite.mjs from server/catalyst/schema.sql — do not edit by hand.
--  To change a table: edit schema.sql, run the generator, and add the difference as a new migration file
--  backend/migrations/shop/NNNN_<what>.sql (ALTER TABLE …). The tests check the migrations add up to this file.
--
--  Same tables, columns and relations as the approved design (see server/catalyst/TABLES.md). Mapping:
--    Catalyst ROWID              → "id" INTEGER PRIMARY KEY AUTOINCREMENT (never reused; the API calls it ROWID)
--    CREATEDTIME / MODIFIEDTIME  → "created_at" / "updated_at"  TEXT, ISO-8601 UTC (set automatically)
--    VARCHAR(n) / TEXT           → TEXT  (max length checked by the API, so it can grow without a table rebuild)
--    INT / BIGINT / FK ids       → INTEGER   · money in paise, qty in thousandths, % in basis points
--    BOOLEAN                     → INTEGER 0 / 1
--    DATE / DATETIME             → TEXT  YYYY-MM-DD / ISO-8601 UTC (sorts and compares correctly)
--    ENCRYPTED                   → TEXT holding AES-256-GCM ciphertext (the API encrypts with SECRETS_KEY)
--    Fixed lists (enums)         → INTEGER codes from server/catalyst/enums.ts (CHECK >= 1 only, so a new
--                                   value never needs a migration). Never renumber; add at the end.
--    FK → x CASCADE / NULL       → REFERENCES x("id") ON DELETE CASCADE / SET NULL — only when x is in this
--                                   database; a reference to the other database is a plain INTEGER.
--  The API turns on foreign keys ("PRAGMA foreign_keys = ON") on every connection.
-- =====================================================================================================

-- Secrets (WhatsApp tokens etc.) — the only place they are kept. Never returned to a browser.
CREATE TABLE IF NOT EXISTS "secrets" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "owner_type"               INTEGER  NOT NULL CHECK ("owner_type" >= 1),  -- SecretOwner: 1 platform, 2 business
  "business_id"              INTEGER,  -- → businesses.id in the platform database (checked by the API) · NULL for platform secrets
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- SecretKind: 1 whatsapp_token
  "value"                    TEXT     NOT NULL,  -- AES-256-GCM ciphertext (encrypted in the API)
  "last4"                    TEXT,  -- max 4
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 120 · '<owner_type>:<business_id|0>:<kind>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "secrets_updated_at" AFTER UPDATE ON "secrets" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "secrets" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_secrets_business_id" ON "secrets" ("business_id");

CREATE TABLE IF NOT EXISTS "branches" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 120
  "code"                     TEXT,  -- max 10 · short code, e.g. ADY
  "address"                  TEXT,  -- max 255
  "phone"                    TEXT,  -- max 16
  "gstin"                    TEXT,  -- max 15 · a branch in another state has its own GSTIN
  "is_default"               INTEGER  NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)),
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "invoice_prefix"           TEXT,  -- max 10 · own bill series, e.g. 'AD-'; NULL = business series
  "printer_json"             TEXT,  -- receipt printer setup: {transport, paper, mode, autoPrint, copies, cut, drawer, baudRate}
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "branches_updated_at" AFTER UPDATE ON "branches" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "branches" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_branches_business_id" ON "branches" ("business_id");

CREATE TABLE IF NOT EXISTS "roles" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 60 · Owner | Manager | Cashier | Waiter | Kitchen | custom
  "system_key"               INTEGER  CHECK ("system_key" IS NULL OR "system_key" >= 1),  -- RoleKey: 1 owner, 2 manager, 3 cashier, 4 waiter, 5 kitchen; NULL = custom role
  "is_all_access"            INTEGER  NOT NULL DEFAULT 0 CHECK ("is_all_access" IN (0, 1)),  -- owner
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 100 · '<business_id>:<lower(name)>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "roles_updated_at" AFTER UPDATE ON "roles" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "roles" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_roles_business_id" ON "roles" ("business_id");

CREATE TABLE IF NOT EXISTS "tax_rates" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 40 · 'GST 5%'
  "rate_bp"                  INTEGER  NOT NULL,  -- 500
  "is_inclusive"             INTEGER  NOT NULL DEFAULT 0 CHECK ("is_inclusive" IN (0, 1)),  -- prices include tax
  "is_default"               INTEGER  NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)),
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "tax_rates_updated_at" AFTER UPDATE ON "tax_rates" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "tax_rates" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_tax_rates_business_id" ON "tax_rates" ("business_id");

-- Price lists: Retail (default) + any number of others (Contractor, Wholesale, Dealer…).
CREATE TABLE IF NOT EXISTS "price_lists" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 60 · 'Contractor rate'
  "is_default"               INTEGER  NOT NULL DEFAULT 0 CHECK ("is_default" IN (0, 1)),  -- retail = products.price_minor
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 100 · '<business_id>:<lower(name)>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "price_lists_updated_at" AFTER UPDATE ON "price_lists" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "price_lists" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_price_lists_business_id" ON "price_lists" ("business_id");

CREATE TABLE IF NOT EXISTS "suppliers" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 150
  "phone"                    TEXT,  -- max 16
  "gstin"                    TEXT,  -- max 15
  "address"                  TEXT,  -- max 255
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "state_code"               TEXT,  -- max 2 · GST state (01–38); from the GSTIN when given — decides IGST vs CGST + SGST
  "opening_balance_minor"    INTEGER  NOT NULL DEFAULT 0,  -- owed to the supplier before using the app (+) or advance paid (−)
  "notes"                    TEXT,  -- max 255
  "name_key"                 TEXT,  -- max 200 · '<business_id>:<lower(name)>' — duplicate check (enforced by the API)
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "suppliers_updated_at" AFTER UPDATE ON "suppliers" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "suppliers" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_suppliers_business_id" ON "suppliers" ("business_id");

CREATE TABLE IF NOT EXISTS "expense_categories" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 60 · Purchase | Salary | Rent | Electricity | Transport | Maintenance | Other | custom
  "system_key"               INTEGER  CHECK ("system_key" IS NULL OR "system_key" >= 1),  -- ExpenseKey: 1 purchase, 2 salary, 3 rent, 4 electricity, 5 transport, 6 maintenance, 7 other
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 100 · '<business_id>:<lower(name)>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "expense_categories_updated_at" AFTER UPDATE ON "expense_categories" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "expense_categories" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_expense_categories_business_id" ON "expense_categories" ("business_id");

-- Message templates — the customer's (business_id set) and the platform's (business_id NULL).
CREATE TABLE IF NOT EXISTS "whatsapp_templates" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER,  -- → businesses.id in the platform database (checked by the API)
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- WaTemplateKind: 1 bill, 2 offer, 3 renewal_reminder
  "language"                 TEXT     NOT NULL,  -- max 5 · en | ta
  "body"                     TEXT     NOT NULL,
  "attach"                   INTEGER  NOT NULL DEFAULT 0 CHECK ("attach" IN (0, 1)),  -- PDF / poster header
  "meta_template_name"       TEXT,  -- max 80
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- WaTemplateStatus: 1 draft, 2 pending, 3 approved, 4 rejected
  "reject_reason"            TEXT,  -- max 255
  "submitted_at"             TEXT,
  "approved_at"              TEXT,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<business_id|platform>:<kind>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "whatsapp_templates_updated_at" AFTER UPDATE ON "whatsapp_templates" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "whatsapp_templates" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_whatsapp_templates_business_id" ON "whatsapp_templates" ("business_id");

-- Number series (bill, order, KOT, credit note, ticket …). Read-and-increment with row_version check.
CREATE TABLE IF NOT EXISTS "sequences" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  REFERENCES "branches"("id") ON DELETE CASCADE,  -- NULL = business-wide series
  "name"                     INTEGER  NOT NULL CHECK ("name" >= 1),  -- SequenceName: 1 invoice, 2 order, 3 kot, 4 credit_note, 5 purchase
  "prefix"                   TEXT     NOT NULL DEFAULT '',  -- max 20
  "next_value"               INTEGER  NOT NULL DEFAULT 1,
  "fiscal_year"              TEXT,  -- max 9 · '2026-27' when the series restarts every April
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<business_id>:<branch_id|0>:<name>:<fiscal_year|->'
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "sequences_updated_at" AFTER UPDATE ON "sequences" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "sequences" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_sequences_business_id" ON "sequences" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_sequences_branch_id" ON "sequences" ("branch_id");

-- POS devices (counters, waiter phones, kitchen screens). For offline sync.
CREATE TABLE IF NOT EXISTS "devices" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "name"                     TEXT     NOT NULL,  -- max 80 · 'Counter 1'
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- DeviceKind: 1 counter, 2 waiter, 3 kitchen, 4 display
  "device_uuid"              TEXT     NOT NULL UNIQUE,  -- max 40
  "platform"                 INTEGER  CHECK ("platform" IS NULL OR "platform" >= 1),  -- DevicePlatform: 1 web, 2 android, 3 ios
  "app_version"              TEXT,  -- max 20
  "last_seen_at"             TEXT,
  "last_sync_at"             TEXT,
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "devices_updated_at" AFTER UPDATE ON "devices" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "devices" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_devices_business_id" ON "devices" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_devices_branch_id" ON "devices" ("branch_id");

CREATE TABLE IF NOT EXISTS "role_permissions" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "role_id"                  INTEGER  NOT NULL REFERENCES "roles"("id") ON DELETE CASCADE,
  "permission"               TEXT     NOT NULL,  -- max 40 · billing.create | orders.cancel | reports.profit | …
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<role_id>:<permission>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "role_permissions_updated_at" AFTER UPDATE ON "role_permissions" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "role_permissions" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_role_permissions_role_id" ON "role_permissions" ("role_id");

CREATE TABLE IF NOT EXISTS "users" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "role_id"                  INTEGER  REFERENCES "roles"("id") ON DELETE SET NULL,
  "default_branch_id"        INTEGER  REFERENCES "branches"("id") ON DELETE SET NULL,
  "name"                     TEXT     NOT NULL,  -- max 120
  "phone"                    TEXT     NOT NULL UNIQUE,  -- max 16 · E.164, sign-in ID
  "email"                    TEXT,  -- max 150
  "username"                 TEXT     UNIQUE,  -- max 40 · owner login created by the product admin
  "catalyst_user_id"         INTEGER  UNIQUE,  -- only if Catalyst Authentication is used later
  "password_hash"            TEXT,  -- max 100 · bcrypt of the password the admin gives; never plain text
  "can_login"                INTEGER  NOT NULL DEFAULT 1 CHECK ("can_login" IN (0, 1)),  -- false = staff who don't use the app (cleaners, helpers): attendance & salary only
  "must_change_password"     INTEGER  NOT NULL DEFAULT 1 CHECK ("must_change_password" IN (0, 1)),  -- ask for a new password on first sign-in
  "password_changed_at"      TEXT,
  "failed_logins"            INTEGER  NOT NULL DEFAULT 0,  -- lock for 15 min after 5 wrong tries
  "locked_until"             TEXT,
  "token_version"            INTEGER  NOT NULL DEFAULT 1,  -- in the sign-in token; +1 on password reset / turn off → old sessions end
  "language"                 TEXT     NOT NULL DEFAULT 'en',  -- max 5 · en | ta | …
  "pin_hash"                 TEXT,  -- max 100 · optional quick PIN for shared counters (bcrypt) staff pay
  "pay_type"                 INTEGER  CHECK ("pay_type" IS NULL OR "pay_type" >= 1),  -- PayType: 1 monthly, 2 daily; NULL = not on payroll
  "pay_amount_minor"         INTEGER  NOT NULL DEFAULT 0,
  "commission_bp"            INTEGER  NOT NULL DEFAULT 0,  -- % of own net sales
  "joined_on"                TEXT     CHECK ("joined_on" IS NULL OR "joined_on" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "last_login_at"            TEXT,
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "users_updated_at" AFTER UPDATE ON "users" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "users" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_users_business_id_is_active" ON "users" ("business_id", "is_active");
CREATE INDEX IF NOT EXISTS "ix_users_role_id" ON "users" ("role_id");
CREATE INDEX IF NOT EXISTS "ix_users_default_branch_id" ON "users" ("default_branch_id");

CREATE TABLE IF NOT EXISTS "customers" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "name"                     TEXT     NOT NULL,  -- max 120
  "phone"                    TEXT,  -- max 16 · E.164
  "phone_key"                TEXT     UNIQUE,  -- max 60 · '<business_id>:<phone>' (NULL when no phone)
  "email"                    TEXT,  -- max 150
  "address"                  TEXT,  -- max 255
  "gstin"                    TEXT,  -- max 15 · B2B bills
  "price_list_id"            INTEGER  REFERENCES "price_lists"("id") ON DELETE SET NULL,  -- NULL = retail
  "credit_limit_minor"       INTEGER,
  "marketing_opt_in"         INTEGER  NOT NULL DEFAULT 1 CHECK ("marketing_opt_in" IN (0, 1)),
  "notes"                    TEXT,  -- max 255
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "state_code"               TEXT,  -- max 2 · GST place of supply (from the GSTIN when given)
  "points_balance"           INTEGER  NOT NULL DEFAULT 0,  -- loyalty points (sum of customer_points; kept for quick reads)
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "customers_updated_at" AFTER UPDATE ON "customers" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "customers" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_customers_business_id_is_active" ON "customers" ("business_id", "is_active");
CREATE INDEX IF NOT EXISTS "ix_customers_price_list_id" ON "customers" ("price_list_id");

CREATE TABLE IF NOT EXISTS "dining_tables" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "label"                    TEXT     NOT NULL,  -- max 20 · T1, Patio 2
  "area"                     TEXT,  -- max 40
  "seats"                    INTEGER  NOT NULL DEFAULT 4,
  "qr_token"                 TEXT     UNIQUE,  -- max 40 · QR menu link for this table
  "merged_into_id"           INTEGER  REFERENCES "dining_tables"("id") ON DELETE SET NULL,  -- tables merged for a big group → the main table
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<branch_id>:<lower(label)>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "dining_tables_updated_at" AFTER UPDATE ON "dining_tables" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "dining_tables" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_dining_tables_business_id" ON "dining_tables" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_dining_tables_branch_id" ON "dining_tables" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_dining_tables_merged_into_id" ON "dining_tables" ("merged_into_id");

CREATE TABLE IF NOT EXISTS "whatsapp_accounts" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL UNIQUE,  -- → businesses.id in the platform database (checked by the API) · one per business
  "provider"                 INTEGER  NOT NULL DEFAULT 1 CHECK ("provider" >= 1),  -- WaProvider: 1 meta_cloud
  "business_number"          TEXT,  -- max 16 · empty until the shop connects its account
  "waba_id"                  TEXT,  -- max 25
  "phone_number_id"          TEXT,  -- max 25
  "secret_id"                INTEGER  REFERENCES "secrets"("id") ON DELETE SET NULL,  -- access token
  "verified_name"            TEXT,  -- max 120
  "quality"                  INTEGER  CHECK ("quality" IS NULL OR "quality" >= 1),  -- WaQuality: 1 high, 2 medium, 3 low
  "verified_at"              TEXT,
  "auto_send_bill"           INTEGER  NOT NULL DEFAULT 0 CHECK ("auto_send_bill" IN (0, 1)),
  "setup_done_at"            TEXT,
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- WaAccountStatus: 1 setup, 2 connected, 3 disconnected
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "whatsapp_accounts_updated_at" AFTER UPDATE ON "whatsapp_accounts" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "whatsapp_accounts" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_whatsapp_accounts_secret_id" ON "whatsapp_accounts" ("secret_id");

-- Key / value business settings: 'billing', 'terminology', 'modules', 'qr', 'wholesale', … (JSON each).
CREATE TABLE IF NOT EXISTS "business_settings" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "setting_key"              TEXT     NOT NULL,  -- max 40
  "value_json"               TEXT     NOT NULL,
  "schema_version"           INTEGER  NOT NULL DEFAULT 1,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<business_id>:<setting_key>'
  "updated_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "business_settings_updated_at" AFTER UPDATE ON "business_settings" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "business_settings" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_business_settings_business_id" ON "business_settings" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_business_settings_updated_by" ON "business_settings" ("updated_by");

-- Images and files stored in Stratus.
CREATE TABLE IF NOT EXISTS "media_files" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER,  -- → businesses.id in the platform database (checked by the API) · NULL = platform file
  "purpose"                  INTEGER  NOT NULL CHECK ("purpose" >= 1),  -- MediaPurpose: 1 product, 2 category, 3 logo, 4 ticket, 5 poster
  "bucket"                   TEXT     NOT NULL,  -- max 60
  "object_key"               TEXT     NOT NULL UNIQUE,  -- max 255 · '<business_id>/products/<uuid>.webp'
  "thumb_key"                TEXT,  -- max 255
  "content_type"             TEXT     NOT NULL,  -- max 40 · image/webp | application/zip | …
  "bytes"                    INTEGER  NOT NULL,  -- photos ≤ 51,200
  "width"                    INTEGER,
  "height"                   INTEGER,
  "original_bytes"           INTEGER,
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "media_files_updated_at" AFTER UPDATE ON "media_files" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "media_files" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_media_files_business_id" ON "media_files" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_media_files_created_by" ON "media_files" ("created_by");

-- Branches a staff member may work in (all-access roles don't need rows).
CREATE TABLE IF NOT EXISTS "user_branches" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "user_id"                  INTEGER  NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<user_id>:<branch_id>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "user_branches_updated_at" AFTER UPDATE ON "user_branches" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "user_branches" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_user_branches_user_id" ON "user_branches" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_user_branches_branch_id" ON "user_branches" ("branch_id");

-- Purchase / stock-in bills.
CREATE TABLE IF NOT EXISTS "purchases" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "supplier_id"              INTEGER  REFERENCES "suppliers"("id") ON DELETE SET NULL,
  "number"                   TEXT     NOT NULL,  -- max 30
  "supplier_bill_no"         TEXT,  -- max 40
  "purchase_date"            TEXT     NOT NULL CHECK ("purchase_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "subtotal_minor"           INTEGER  NOT NULL DEFAULT 0,
  "tax_minor"                INTEGER  NOT NULL DEFAULT 0,
  "total_minor"              INTEGER  NOT NULL DEFAULT 0,
  "paid_minor"               INTEGER  NOT NULL DEFAULT 0,
  "status"                   INTEGER  NOT NULL DEFAULT 2 CHECK ("status" >= 1),  -- PurchaseStatus: 1 draft, 2 final, 3 void
  "note"                     TEXT,  -- max 255
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "client_uuid"              TEXT,  -- max 40 · retry safety (checked by the API before insert)
  "is_igst"                  INTEGER  NOT NULL DEFAULT 0 CHECK ("is_igst" IN (0, 1)),  -- supplier in another state: tax is IGST (input credit)
  "round_off_minor"          INTEGER  NOT NULL DEFAULT 0,
  "void_reason"              TEXT,  -- max 255
  "voided_at"                TEXT,
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "purchases_updated_at" AFTER UPDATE ON "purchases" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "purchases" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_purchases_business_id" ON "purchases" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_purchases_branch_id" ON "purchases" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_purchases_supplier_id" ON "purchases" ("supplier_id");
CREATE INDEX IF NOT EXISTS "ix_purchases_created_by" ON "purchases" ("created_by");

-- An order becomes a bill when it is completed (invoice_number is given then).
CREATE TABLE IF NOT EXISTS "orders" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "device_id"                INTEGER  REFERENCES "devices"("id") ON DELETE SET NULL,
  "client_uuid"              TEXT     NOT NULL UNIQUE,  -- max 40 · idempotency / offline
  "order_number"             TEXT     NOT NULL,  -- max 30 · #2209
  "invoice_number"           TEXT,  -- max 30 · INV-11186, set on completion
  "invoice_key"              TEXT     UNIQUE,  -- max 80 · '<business_id>:<invoice_number>'
  "order_type"               INTEGER  NOT NULL CHECK ("order_type" >= 1),  -- OrderType: 1 dine_in, 2 takeaway, 3 delivery, 4 counter
  "source"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("source" >= 1),  -- OrderSource: 1 pos, 2 mobile, 3 table, 4 qr
  "status"                   INTEGER  NOT NULL CHECK ("status" >= 1),  -- OrderStatus: 1 open, 2 completed, 3 cancelled
  "table_id"                 INTEGER  REFERENCES "dining_tables"("id") ON DELETE SET NULL,
  "customer_id"              INTEGER  REFERENCES "customers"("id") ON DELETE SET NULL,
  "customer_name"            TEXT,  -- max 120 · snapshot / walk-in guest
  "customer_phone"           TEXT,  -- max 16
  "customer_address"         TEXT,  -- max 255 · delivery / QR takeaway
  "qr_status"                INTEGER  CHECK ("qr_status" IS NULL OR "qr_status" >= 1),  -- QrStatus: 1 pending, 2 accepted, 3 rejected; NULL = not a QR order
  "fulfilment"               INTEGER  CHECK ("fulfilment" IS NULL OR "fulfilment" >= 1),  -- Fulfilment: 1 new, 2 packing, 3 ready, 4 delivered; NULL = normal counter bill
  "price_list_id"            INTEGER  REFERENCES "price_lists"("id") ON DELETE SET NULL,
  "guests"                   INTEGER,
  "subtotal_minor"           INTEGER  NOT NULL DEFAULT 0,
  "discount_minor"           INTEGER  NOT NULL DEFAULT 0,
  "discount_note"            TEXT,  -- max 100
  "tax_minor"                INTEGER  NOT NULL DEFAULT 0,
  "service_charge_minor"     INTEGER  NOT NULL DEFAULT 0,
  "round_off_minor"          INTEGER  NOT NULL DEFAULT 0,  -- ±
  "total_minor"              INTEGER  NOT NULL DEFAULT 0,
  "paid_minor"               INTEGER  NOT NULL DEFAULT 0,
  "balance_minor"            INTEGER  NOT NULL DEFAULT 0,  -- due (credit)
  "returned_minor"           INTEGER  NOT NULL DEFAULT 0,  -- sum of sale_returns
  "tax_breakup_json"         TEXT,  -- [{rate_bp, taxable_minor, cgst_minor, sgst_minor, igst_minor}]
  "note"                     TEXT,  -- max 255
  "billed_at"                TEXT,
  "cancelled_at"             TEXT,
  "cancel_reason"            TEXT,  -- max 255
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,  -- staff on the bill (commission)
  "salesperson_id"           INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,  -- who sold it (textile counters); NULL = the person who made the bill
  "customer_gstin"           TEXT,  -- max 15 · snapshot at billing: B2B tax invoice
  "place_of_supply"          TEXT,  -- max 2 · GST state code of the customer (snapshot); NULL = shop's state
  "is_igst"                  INTEGER  NOT NULL DEFAULT 0 CHECK ("is_igst" IN (0, 1)),  -- other-state customer: IGST instead of CGST + SGST
  "points_redeemed"          INTEGER  NOT NULL DEFAULT 0,  -- loyalty points used on this bill
  "points_value_minor"       INTEGER  NOT NULL DEFAULT 0,  -- their value (part of discount_minor, given before GST)
  "points_earned"            INTEGER  NOT NULL DEFAULT 0,
  "points_balance_after"     INTEGER,  -- customer's points after this bill (printed)
  "updated_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "orders_updated_at" AFTER UPDATE ON "orders" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "orders" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_orders_business_id_branch_id_status_created_at" ON "orders" ("business_id", "branch_id", "status", "created_at");
CREATE INDEX IF NOT EXISTS "ix_orders_business_id_billed_at" ON "orders" ("business_id", "billed_at");
CREATE INDEX IF NOT EXISTS "ix_orders_business_id_customer_id_status" ON "orders" ("business_id", "customer_id", "status");
CREATE INDEX IF NOT EXISTS "ix_orders_business_id_table_id_status" ON "orders" ("business_id", "table_id", "status");
CREATE INDEX IF NOT EXISTS "ix_orders_business_id_order_number" ON "orders" ("business_id", "order_number");
CREATE INDEX IF NOT EXISTS "ix_orders_branch_id" ON "orders" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_orders_device_id" ON "orders" ("device_id");
CREATE INDEX IF NOT EXISTS "ix_orders_table_id" ON "orders" ("table_id");
CREATE INDEX IF NOT EXISTS "ix_orders_customer_id" ON "orders" ("customer_id");
CREATE INDEX IF NOT EXISTS "ix_orders_price_list_id" ON "orders" ("price_list_id");
CREATE INDEX IF NOT EXISTS "ix_orders_created_by" ON "orders" ("created_by");
CREATE INDEX IF NOT EXISTS "ix_orders_salesperson_id" ON "orders" ("salesperson_id");
CREATE INDEX IF NOT EXISTS "ix_orders_updated_by" ON "orders" ("updated_by");

CREATE TABLE IF NOT EXISTS "expenses" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "category_id"              INTEGER  REFERENCES "expense_categories"("id") ON DELETE SET NULL,
  "expense_date"             TEXT     NOT NULL,
  "amount_minor"             INTEGER  NOT NULL,
  "method"                   INTEGER  NOT NULL CHECK ("method" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank, 5 credit_note
  "notes"                    TEXT,  -- max 255
  "ref_type"                 INTEGER  CHECK ("ref_type" IS NULL OR "ref_type" >= 1),  -- ExpenseRef: 1 salary, 2 advance, 3 purchase, 4 supplier_payment
  "ref_id"                   INTEGER,
  "is_voided"                INTEGER  NOT NULL DEFAULT 0 CHECK ("is_voided" IN (0, 1)),
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "expenses_updated_at" AFTER UPDATE ON "expenses" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "expenses" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_expenses_business_id_branch_id_expense_date" ON "expenses" ("business_id", "branch_id", "expense_date");
CREATE INDEX IF NOT EXISTS "ix_expenses_branch_id" ON "expenses" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_expenses_category_id" ON "expenses" ("category_id");
CREATE INDEX IF NOT EXISTS "ix_expenses_created_by" ON "expenses" ("created_by");

CREATE TABLE IF NOT EXISTS "attendance" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "user_id"                  INTEGER  NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "work_date"                TEXT     NOT NULL CHECK ("work_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "status"                   INTEGER  NOT NULL CHECK ("status" >= 1),  -- AttendanceStatus: 1 present, 2 half, 3 absent, 4 leave
  "in_time"                  TEXT,  -- max 5 · '09:30'
  "out_time"                 TEXT,  -- max 5
  "note"                     TEXT,  -- max 150
  "marked_by"                INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<user_id>:<work_date>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "attendance_updated_at" AFTER UPDATE ON "attendance" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "attendance" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_attendance_business_id_work_date" ON "attendance" ("business_id", "work_date");
CREATE INDEX IF NOT EXISTS "ix_attendance_branch_id" ON "attendance" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_attendance_user_id" ON "attendance" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_attendance_marked_by" ON "attendance" ("marked_by");

-- What the shop's staff did (Settings → Audit log).
CREATE TABLE IF NOT EXISTS "audit_logs" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  REFERENCES "branches"("id") ON DELETE SET NULL,
  "user_id"                  INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "support_admin_id"         INTEGER,  -- → platform_admins.id in the platform database (checked by the API) · set during a support view
  "entity"                   INTEGER  NOT NULL CHECK ("entity" >= 1),  -- AuditEntity: 1 order, 2 payment, 3 product, 4 category, 5 customer, 6 inventory, 7 expense, 8 user, 9 role, 10 branch, 11 settings, 12 whatsapp, 13 return, 14 staff, 15 table
  "entity_id"                INTEGER,
  "action"                   INTEGER  NOT NULL CHECK ("action" >= 1),  -- AuditAction: 1 create, 2 update, 3 delete, 4 cancel, 5 void, 6 login, 7 printer, 8 enable, 9 disconnect, 10 import, 11 export
  "detail"                   TEXT,  -- max 255
  "changes_json"             TEXT,  -- {field: [old, new]}
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "audit_logs_updated_at" AFTER UPDATE ON "audit_logs" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "audit_logs" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_audit_logs_business_id_created_at" ON "audit_logs" ("business_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_audit_logs_branch_id" ON "audit_logs" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_audit_logs_user_id" ON "audit_logs" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_audit_logs_support_admin_id" ON "audit_logs" ("support_admin_id");

CREATE TABLE IF NOT EXISTS "categories" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "parent_id"                INTEGER  REFERENCES "categories"("id") ON DELETE SET NULL,  -- sub-categories later
  "name"                     TEXT     NOT NULL,  -- max 80
  "emoji"                    TEXT,  -- max 8
  "image_media_id"           INTEGER  REFERENCES "media_files"("id") ON DELETE SET NULL,
  "hsn_code"                 TEXT,  -- max 10 · default HSN / SAC for items in this category (item's own wins)
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 120 · '<business_id>:<lower(name)>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "categories_updated_at" AFTER UPDATE ON "categories" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "categories" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_categories_business_id" ON "categories" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_categories_parent_id" ON "categories" ("parent_id");
CREATE INDEX IF NOT EXISTS "ix_categories_image_media_id" ON "categories" ("image_media_id");

-- Money paid to a supplier (at purchase, or later against the balance). Voided, never edited.
CREATE TABLE IF NOT EXISTS "supplier_payments" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "supplier_id"              INTEGER  NOT NULL REFERENCES "suppliers"("id") ON DELETE CASCADE,
  "purchase_id"              INTEGER  REFERENCES "purchases"("id") ON DELETE SET NULL,  -- paid with this purchase bill; NULL = against the balance
  "client_uuid"              TEXT     NOT NULL UNIQUE,  -- max 40
  "method"                   INTEGER  NOT NULL CHECK ("method" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank
  "amount_minor"             INTEGER  NOT NULL,
  "paid_on"                  TEXT     NOT NULL CHECK ("paid_on" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "reference"                TEXT,  -- max 80
  "note"                     TEXT,  -- max 255
  "is_voided"                INTEGER  NOT NULL DEFAULT 0 CHECK ("is_voided" IN (0, 1)),
  "voided_at"                TEXT,
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "supplier_payments_updated_at" AFTER UPDATE ON "supplier_payments" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "supplier_payments" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_supplier_payments_business_id" ON "supplier_payments" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_supplier_payments_branch_id" ON "supplier_payments" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_supplier_payments_supplier_id" ON "supplier_payments" ("supplier_id");
CREATE INDEX IF NOT EXISTS "ix_supplier_payments_purchase_id" ON "supplier_payments" ("purchase_id");
CREATE INDEX IF NOT EXISTS "ix_supplier_payments_created_by" ON "supplier_payments" ("created_by");

-- Returns / credit notes.
CREATE TABLE IF NOT EXISTS "sale_returns" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "order_id"                 INTEGER  REFERENCES "orders"("id") ON DELETE SET NULL,
  "customer_id"              INTEGER  REFERENCES "customers"("id") ON DELETE SET NULL,
  "client_uuid"              TEXT     NOT NULL UNIQUE,  -- max 40
  "number"                   TEXT     NOT NULL,  -- max 30 · CN-1001
  "number_key"               TEXT     NOT NULL UNIQUE,  -- max 80 · '<business_id>:<number>'
  "invoice_number"           TEXT     NOT NULL,  -- max 30 · snapshot of the bill
  "reason"                   INTEGER  NOT NULL CHECK ("reason" >= 1),  -- ReturnReason: 1 damaged, 2 wrong_item, 3 not_needed, 4 expired, 5 quality, 6 other
  "settle"                   INTEGER  NOT NULL CHECK ("settle" >= 1),  -- ReturnSettle: 1 refund, 2 exchange, 3 credit_note
  "note"                     TEXT,  -- max 255
  "total_minor"              INTEGER  NOT NULL,
  "tax_minor"                INTEGER  NOT NULL DEFAULT 0,  -- tax share of the total
  "due_adjusted_minor"       INTEGER  NOT NULL DEFAULT 0,  -- taken off the bill's balance first
  "refunded_minor"           INTEGER  NOT NULL DEFAULT 0,
  "refund_method"            INTEGER  CHECK ("refund_method" IS NULL OR "refund_method" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank, 5 credit_note
  "credit_issued_minor"      INTEGER  NOT NULL DEFAULT 0,
  "credit_remaining_minor"   INTEGER  NOT NULL DEFAULT 0,  -- reduced by payments with method credit_note
  "credit_expires_on"        TEXT     CHECK ("credit_expires_on" IS NULL OR "credit_expires_on" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "sale_returns_updated_at" AFTER UPDATE ON "sale_returns" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "sale_returns" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_sale_returns_business_id_branch_id_created_at" ON "sale_returns" ("business_id", "branch_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_sale_returns_order_id" ON "sale_returns" ("order_id");
CREATE INDEX IF NOT EXISTS "ix_sale_returns_branch_id" ON "sale_returns" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_sale_returns_customer_id" ON "sale_returns" ("customer_id");
CREATE INDEX IF NOT EXISTS "ix_sale_returns_created_by" ON "sale_returns" ("created_by");

CREATE TABLE IF NOT EXISTS "kitchen_tickets" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "order_id"                 INTEGER  NOT NULL REFERENCES "orders"("id") ON DELETE CASCADE,
  "client_uuid"              TEXT     NOT NULL UNIQUE,  -- max 40
  "number"                   TEXT     NOT NULL,  -- max 20 · KOT-0014
  "order_number"             TEXT     NOT NULL,  -- max 30 · snapshot for the kitchen screen
  "order_type"               INTEGER  NOT NULL,  -- OrderType (snapshot)
  "station"                  TEXT,  -- max 30 · kitchen | bar | grill (later)
  "status"                   INTEGER  NOT NULL DEFAULT 1 CHECK ("status" >= 1),  -- KotStatus: 1 new, 2 preparing, 3 ready, 4 completed, 5 cancelled
  "table_label"              TEXT,  -- max 20 · snapshot
  "started_at"               TEXT,
  "ready_at"                 TEXT,
  "completed_at"             TEXT,  -- served / handed over
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "kitchen_tickets_updated_at" AFTER UPDATE ON "kitchen_tickets" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "kitchen_tickets" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_kitchen_tickets_business_id_branch_id_status" ON "kitchen_tickets" ("business_id", "branch_id", "status");
CREATE INDEX IF NOT EXISTS "ix_kitchen_tickets_order_id" ON "kitchen_tickets" ("order_id");
CREATE INDEX IF NOT EXISTS "ix_kitchen_tickets_branch_id" ON "kitchen_tickets" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_kitchen_tickets_created_by" ON "kitchen_tickets" ("created_by");

-- Browser push for the QR / order tracking page ("Notify me when ready"). Removed when the order is done or after a day.
CREATE TABLE IF NOT EXISTS "push_subscriptions" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "order_id"                 INTEGER  NOT NULL REFERENCES "orders"("id") ON DELETE CASCADE,
  "endpoint"                 TEXT     NOT NULL,  -- max 500 · push service URL (Google / Apple / Mozilla)
  "p256dh"                   TEXT     NOT NULL,  -- max 120 · the browser's public key (base64url)
  "auth_secret"              TEXT     NOT NULL,  -- max 40 · the browser's auth secret (base64url)
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<order_id>:<hash of endpoint>'
  "last_stamp"               TEXT,  -- max 40 · status last sent, so each change is sent once
  "expires_at"               TEXT     NOT NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "push_subscriptions_updated_at" AFTER UPDATE ON "push_subscriptions" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "push_subscriptions" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_push_subscriptions_business_id_expires_at" ON "push_subscriptions" ("business_id", "expires_at");
CREATE INDEX IF NOT EXISTS "ix_push_subscriptions_order_id" ON "push_subscriptions" ("order_id");

CREATE TABLE IF NOT EXISTS "salary_payments" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "user_id"                  INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "month"                    TEXT     NOT NULL,  -- max 7 · '2026-10' snapshot of how it was worked out, so an old salary slip reprints exactly
  "pay_type"                 INTEGER  NOT NULL,  -- PayType
  "rate_minor"               INTEGER  NOT NULL,  -- monthly salary or daily rate at that time
  "days_in_month"            INTEGER  NOT NULL,
  "present_days"             INTEGER  NOT NULL DEFAULT 0,
  "half_days"                INTEGER  NOT NULL DEFAULT 0,
  "leave_days"               INTEGER  NOT NULL DEFAULT 0,
  "absent_days"              INTEGER  NOT NULL DEFAULT 0,
  "unmarked_days"            INTEGER  NOT NULL DEFAULT 0,
  "commission_sales_minor"   INTEGER  NOT NULL DEFAULT 0,  -- net sales the commission was worked out on
  "base_minor"               INTEGER  NOT NULL,
  "commission_minor"         INTEGER  NOT NULL DEFAULT 0,
  "bonus_minor"              INTEGER  NOT NULL DEFAULT 0,
  "deduction_minor"          INTEGER  NOT NULL DEFAULT 0,
  "advances_minor"           INTEGER  NOT NULL DEFAULT 0,
  "net_minor"                INTEGER  NOT NULL,
  "method"                   INTEGER  NOT NULL,  -- PayMethod
  "note"                     TEXT,  -- max 150
  "expense_id"               INTEGER  REFERENCES "expenses"("id") ON DELETE SET NULL,
  "paid_by"                  INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 40 · '<user_id>:<month>' — no double pay
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "salary_payments_updated_at" AFTER UPDATE ON "salary_payments" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "salary_payments" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_salary_payments_business_id" ON "salary_payments" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_salary_payments_user_id" ON "salary_payments" ("user_id");
CREATE INDEX IF NOT EXISTS "ix_salary_payments_expense_id" ON "salary_payments" ("expense_id");
CREATE INDEX IF NOT EXISTS "ix_salary_payments_paid_by" ON "salary_payments" ("paid_by");

CREATE TABLE IF NOT EXISTS "campaigns" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "channel"                  INTEGER  NOT NULL DEFAULT 1 CHECK ("channel" >= 1),  -- Channel: 1 whatsapp
  "campaign_date"            TEXT     NOT NULL CHECK ("campaign_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "message"                  TEXT     NOT NULL,  -- offer details (up to 300 characters)
  "product_ids_json"         TEXT,
  "poster_media_id"          INTEGER  REFERENCES "media_files"("id") ON DELETE SET NULL,
  "sent_count"               INTEGER  NOT NULL DEFAULT 0,
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "campaigns_updated_at" AFTER UPDATE ON "campaigns" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "campaigns" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_campaigns_business_id" ON "campaigns" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_campaigns_poster_media_id" ON "campaigns" ("poster_media_id");
CREATE INDEX IF NOT EXISTS "ix_campaigns_created_by" ON "campaigns" ("created_by");

CREATE TABLE IF NOT EXISTS "products" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "category_id"              INTEGER  REFERENCES "categories"("id") ON DELETE SET NULL,
  "tax_rate_id"              INTEGER  REFERENCES "tax_rates"("id") ON DELETE SET NULL,
  "name"                     TEXT     NOT NULL,  -- max 150
  "name_local"               TEXT,  -- max 150 · Tamil name for bills / labels
  "kind"                     INTEGER  NOT NULL DEFAULT 1 CHECK ("kind" >= 1),  -- ProductKind: 1 goods, 2 service
  "sku"                      TEXT,  -- max 40
  "barcode"                  TEXT,  -- max 40
  "barcode_key"              TEXT     UNIQUE,  -- max 80 · '<business_id>:<barcode>' (NULL when no barcode)
  "hsn_code"                 TEXT,  -- max 10
  "unit"                     TEXT     NOT NULL DEFAULT 'pc',  -- max 10 · pc | kg | g | ltr | ml | pack | box | bottle | plate | … (open list: templates and CSV add more)
  "price_minor"              INTEGER  NOT NULL DEFAULT 0,  -- retail price (default price list)
  "mrp_minor"                INTEGER,
  "cost_minor"               INTEGER,
  "is_veg"                   INTEGER  CHECK ("is_veg" IS NULL OR "is_veg" IN (0, 1)),  -- food only
  "sends_to_kitchen"         INTEGER  NOT NULL DEFAULT 1 CHECK ("sends_to_kitchen" IN (0, 1)),  -- KOT
  "track_stock"              INTEGER  NOT NULL DEFAULT 0 CHECK ("track_stock" IN (0, 1)),
  "track_batches"            INTEGER  NOT NULL DEFAULT 0 CHECK ("track_batches" IN (0, 1)),  -- batch & expiry
  "low_stock_milli"          INTEGER  NOT NULL DEFAULT 0,
  "image_media_id"           INTEGER  REFERENCES "media_files"("id") ON DELETE SET NULL,
  "emoji"                    TEXT,  -- max 8
  "details_json"             TEXT,  -- textile shops: {"design","fabric","colour","size"} (printed on price stickers)
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "products_updated_at" AFTER UPDATE ON "products" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "products" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_products_business_id_is_active" ON "products" ("business_id", "is_active");
CREATE INDEX IF NOT EXISTS "ix_products_category_id" ON "products" ("category_id");
CREATE INDEX IF NOT EXISTS "ix_products_tax_rate_id" ON "products" ("tax_rate_id");
CREATE INDEX IF NOT EXISTS "ix_products_image_media_id" ON "products" ("image_media_id");

-- Loyalty points: every earn / use / reversal / expiry / manual change, with the balance after it.
CREATE TABLE IF NOT EXISTS "customer_points" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  REFERENCES "branches"("id") ON DELETE SET NULL,
  "customer_id"              INTEGER  NOT NULL REFERENCES "customers"("id") ON DELETE CASCADE,
  "order_id"                 INTEGER  REFERENCES "orders"("id") ON DELETE SET NULL,
  "return_id"                INTEGER  REFERENCES "sale_returns"("id") ON DELETE SET NULL,
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- PointsKind: 1 earn, 2 redeem, 3 return, 4 cancel, 5 expire, 6 adjust
  "points"                   INTEGER  NOT NULL,  -- + added, − taken
  "balance_after"            INTEGER  NOT NULL,
  "remaining"                INTEGER  NOT NULL DEFAULT 0,  -- earned points not yet used or expired (used oldest first)
  "expires_on"               TEXT     CHECK ("expires_on" IS NULL OR "expires_on" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),  -- earned points only; NULL = never
  "note"                     TEXT,  -- max 150
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "customer_points_updated_at" AFTER UPDATE ON "customer_points" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "customer_points" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_customer_points_business_id" ON "customer_points" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_customer_points_branch_id" ON "customer_points" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_customer_points_customer_id" ON "customer_points" ("customer_id");
CREATE INDEX IF NOT EXISTS "ix_customer_points_order_id" ON "customer_points" ("order_id");
CREATE INDEX IF NOT EXISTS "ix_customer_points_return_id" ON "customer_points" ("return_id");
CREATE INDEX IF NOT EXISTS "ix_customer_points_created_by" ON "customer_points" ("created_by");

-- Every money movement: sale, due collection, refund. Never edited — voided and re-entered.
CREATE TABLE IF NOT EXISTS "payments" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "order_id"                 INTEGER  REFERENCES "orders"("id") ON DELETE SET NULL,  -- NULL for a due collection across bills
  "customer_id"              INTEGER  REFERENCES "customers"("id") ON DELETE SET NULL,
  "return_id"                INTEGER  REFERENCES "sale_returns"("id") ON DELETE SET NULL,  -- refund of / payment with this credit note
  "client_uuid"              TEXT     NOT NULL UNIQUE,  -- max 40
  "kind"                     INTEGER  NOT NULL CHECK ("kind" >= 1),  -- PaymentKind: 1 sale, 2 due_collection, 3 refund
  "method"                   INTEGER  NOT NULL CHECK ("method" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank, 5 credit_note
  "amount_minor"             INTEGER  NOT NULL,
  "reference"                TEXT,  -- max 80 · UPI ref / card last 4
  "is_voided"                INTEGER  NOT NULL DEFAULT 0 CHECK ("is_voided" IN (0, 1)),
  "voided_at"                TEXT,
  "void_reason"              TEXT,  -- max 255
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "payments_updated_at" AFTER UPDATE ON "payments" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "payments" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_payments_business_id_branch_id_created_at" ON "payments" ("business_id", "branch_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_payments_order_id" ON "payments" ("order_id");
CREATE INDEX IF NOT EXISTS "ix_payments_business_id_customer_id" ON "payments" ("business_id", "customer_id");
CREATE INDEX IF NOT EXISTS "ix_payments_branch_id" ON "payments" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_payments_customer_id" ON "payments" ("customer_id");
CREATE INDEX IF NOT EXISTS "ix_payments_return_id" ON "payments" ("return_id");
CREATE INDEX IF NOT EXISTS "ix_payments_created_by" ON "payments" ("created_by");

CREATE TABLE IF NOT EXISTS "staff_advances" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
