CREATE TABLE IF NOT EXISTS "product_addons" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "product_id"               INTEGER  NOT NULL REFERENCES "products"("id") ON DELETE CASCADE,
  "name"                     TEXT     NOT NULL,  -- max 60 · Extra cheese
  "price_minor"              INTEGER  NOT NULL DEFAULT 0,
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "is_active"                INTEGER  NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)),
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "product_addons_updated_at" AFTER UPDATE ON "product_addons" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "product_addons" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_product_addons_business_id" ON "product_addons" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_product_addons_product_id" ON "product_addons" ("product_id");

-- Daily specials (offer price / tag for a date).
