  "offer_price_minor"        INTEGER,
  "tag"                      TEXT,  -- max 40 · 'Chef’s special'
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "daily_specials_updated_at" AFTER UPDATE ON "daily_specials" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "daily_specials" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_daily_specials_business_id_special_date" ON "daily_specials" ("business_id", "special_date");
CREATE INDEX IF NOT EXISTS "ix_daily_specials_branch_id" ON "daily_specials" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_daily_specials_product_id" ON "daily_specials" ("product_id");

-- Current stock per item per branch (kept in step with stock_movements by the backend).
CREATE TABLE IF NOT EXISTS "branch_stock" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "product_id"               INTEGER  NOT NULL REFERENCES "products"("id") ON DELETE CASCADE,
  "qty_milli"                INTEGER  NOT NULL DEFAULT 0,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<branch_id>:<product_id>'
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "branch_stock_updated_at" AFTER UPDATE ON "branch_stock" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "branch_stock" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_branch_stock_business_id" ON "branch_stock" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_branch_stock_branch_id" ON "branch_stock" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_branch_stock_product_id" ON "branch_stock" ("product_id");

CREATE TABLE IF NOT EXISTS "purchase_items" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "purchase_id"              INTEGER  NOT NULL REFERENCES "purchases"("id") ON DELETE CASCADE,
  "product_id"               INTEGER  REFERENCES "products"("id") ON DELETE SET NULL,
  "product_name"             TEXT     NOT NULL,  -- max 150 · snapshot
  "qty_milli"                INTEGER  NOT NULL,
  "cost_minor"               INTEGER  NOT NULL,  -- per unit
  "tax_bp"                   INTEGER  NOT NULL DEFAULT 0,
  "batch_no"                 TEXT,  -- max 40
  "expiry_date"              TEXT     CHECK ("expiry_date" IS NULL OR "expiry_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "unit"                     TEXT,  -- max 10
  "hsn_code"                 TEXT,  -- max 10
  "taxable_minor"            INTEGER,  -- qty × cost (before GST)
  "tax_minor"                INTEGER,
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "purchase_items_updated_at" AFTER UPDATE ON "purchase_items" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "purchase_items" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_purchase_items_business_id" ON "purchase_items" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_purchase_items_purchase_id" ON "purchase_items" ("purchase_id");
CREATE INDEX IF NOT EXISTS "ix_purchase_items_product_id" ON "purchase_items" ("product_id");

