CREATE TRIGGER IF NOT EXISTS "payment_allocations_updated_at" AFTER UPDATE ON "payment_allocations" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "payment_allocations" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_payment_allocations_business_id" ON "payment_allocations" ("business_id");
