CREATE INDEX IF NOT EXISTS "ix_payment_allocations_order_id" ON "payment_allocations" ("order_id");

-- Price of an item (or one of its sizes) on a non-default price list. Missing row → retail price.
CREATE TABLE IF NOT EXISTS "product_prices" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "price_list_id"            INTEGER  NOT NULL REFERENCES "price_lists"("id") ON DELETE CASCADE,
  "product_id"               INTEGER  NOT NULL REFERENCES "products"("id") ON DELETE CASCADE,
  "variant_id"               INTEGER  REFERENCES "product_variants"("id") ON DELETE CASCADE,
  "price_minor"              INTEGER  NOT NULL,
  "uniq_key"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<price_list_id>:<product_id>:<variant_id|0>'
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "product_prices_updated_at" AFTER UPDATE ON "product_prices" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "product_prices" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_product_prices_business_id" ON "product_prices" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_product_prices_price_list_id" ON "product_prices" ("price_list_id");
CREATE INDEX IF NOT EXISTS "ix_product_prices_product_id" ON "product_prices" ("product_id");
CREATE INDEX IF NOT EXISTS "ix_product_prices_variant_id" ON "product_prices" ("variant_id");

-- Batches with expiry (milk, bread, medicines). Sold first-expiry-first-out.
CREATE TABLE IF NOT EXISTS "stock_batches" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "product_id"               INTEGER  NOT NULL REFERENCES "products"("id") ON DELETE CASCADE,
  "purchase_item_id"         INTEGER  REFERENCES "purchase_items"("id") ON DELETE SET NULL,
  "batch_no"                 TEXT,  -- max 40
  "expiry_date"              TEXT     CHECK ("expiry_date" IS NULL OR "expiry_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "qty_in_milli"             INTEGER  NOT NULL,
  "qty_left_milli"           INTEGER  NOT NULL,
  "cost_minor"               INTEGER,
  "row_version"              INTEGER  NOT NULL DEFAULT 1,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "stock_batches_updated_at" AFTER UPDATE ON "stock_batches" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "stock_batches" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_stock_batches_product_id_branch_id_expiry_date" ON "stock_batches" ("product_id", "branch_id", "expiry_date");
CREATE INDEX IF NOT EXISTS "ix_stock_batches_business_id" ON "stock_batches" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_stock_batches_branch_id" ON "stock_batches" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_stock_batches_purchase_item_id" ON "stock_batches" ("purchase_item_id");

CREATE TABLE IF NOT EXISTS "order_items" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "order_id"                 INTEGER  NOT NULL REFERENCES "orders"("id") ON DELETE CASCADE,
  "product_id"               INTEGER  REFERENCES "products"("id") ON DELETE SET NULL,
  "variant_id"               INTEGER  REFERENCES "product_variants"("id") ON DELETE SET NULL,
  "product_name"             TEXT     NOT NULL,  -- max 150 · snapshot: 'French Fries'
  "variant_name"             TEXT,  -- max 60 · snapshot: 'Regular'
  "unit"                     TEXT     NOT NULL,  -- max 10
  "qty_milli"                INTEGER  NOT NULL,
  "unit_price_minor"         INTEGER  NOT NULL,  -- base / size price + add-ons
  "hsn_code"                 TEXT,  -- max 10 · snapshot at billing (item's, else its category's)
  "list_price_minor"         INTEGER,  -- catalogue price when the price was changed at the counter (NULL = not changed)
  "taxable_minor"            INTEGER,  -- value before GST after the bill discount (set at billing)
  "mrp_minor"                INTEGER,  -- printed MRP per unit when it is above the price ("You saved" on the bill)
  "price_list_id"            INTEGER  REFERENCES "price_lists"("id") ON DELETE SET NULL,  -- which list priced it
  "discount_minor"           INTEGER  NOT NULL DEFAULT 0,
  "tax_bp"                   INTEGER  NOT NULL DEFAULT 0,
  "tax_minor"                INTEGER  NOT NULL DEFAULT 0,
  "line_total_minor"         INTEGER  NOT NULL,
  "cost_minor"               INTEGER,  -- snapshot for profit reports
  "note"                     TEXT,  -- max 150 · 'less spicy'
  "kot_qty_milli"            INTEGER  NOT NULL DEFAULT 0,  -- qty already sent to the kitchen (next KOT sends qty − this)
  "sort_order"               INTEGER  NOT NULL DEFAULT 0,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "order_items_updated_at" AFTER UPDATE ON "order_items" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "order_items" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_order_items_order_id_sort_order" ON "order_items" ("order_id", "sort_order");
CREATE INDEX IF NOT EXISTS "ix_order_items_product_id" ON "order_items" ("product_id");
CREATE INDEX IF NOT EXISTS "ix_order_items_business_id" ON "order_items" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_order_items_variant_id" ON "order_items" ("variant_id");
CREATE INDEX IF NOT EXISTS "ix_order_items_price_list_id" ON "order_items" ("price_list_id");

-- Every stock change. The ledger that branch_stock / stock_batches are rebuilt from.
CREATE TABLE IF NOT EXISTS "stock_movements" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "branch_id"                INTEGER  NOT NULL REFERENCES "branches"("id") ON DELETE CASCADE,
  "product_id"               INTEGER  NOT NULL REFERENCES "products"("id") ON DELETE CASCADE,
  "batch_id"                 INTEGER  REFERENCES "stock_batches"("id") ON DELETE SET NULL,
  "reason"                   INTEGER  NOT NULL CHECK ("reason" >= 1),  -- StockReason: 1 opening, 2 purchase, 3 sale, 4 return, 5 wastage, 6 damage, 7 expired, 8 adjustment, 9 transfer_in, 10 transfer_out
  "qty_milli"                INTEGER  NOT NULL,  -- + in, − out
  "balance_milli"            INTEGER  NOT NULL,  -- stock after this movement
  "ref_type"                 INTEGER  CHECK ("ref_type" IS NULL OR "ref_type" >= 1),  -- StockRef: 1 order, 2 purchase, 3 return, 4 transfer
  "ref_id"                   INTEGER,  -- ROWID in that table
  "note"                     TEXT,  -- max 255
  "created_by"               INTEGER  REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "stock_movements_updated_at" AFTER UPDATE ON "stock_movements" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "stock_movements" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_stock_movements_business_id_product_id_created_at" ON "stock_movements" ("business_id", "product_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_stock_movements_business_id_branch_id_created_at" ON "stock_movements" ("business_id", "branch_id", "created_at");
CREATE INDEX IF NOT EXISTS "ix_stock_movements_branch_id" ON "stock_movements" ("branch_id");
CREATE INDEX IF NOT EXISTS "ix_stock_movements_product_id" ON "stock_movements" ("product_id");
CREATE INDEX IF NOT EXISTS "ix_stock_movements_batch_id" ON "stock_movements" ("batch_id");
CREATE INDEX IF NOT EXISTS "ix_stock_movements_created_by" ON "stock_movements" ("created_by");

CREATE TABLE IF NOT EXISTS "order_item_addons" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
