  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "order_item_addons_updated_at" AFTER UPDATE ON "order_item_addons" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "order_item_addons" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_order_item_addons_business_id" ON "order_item_addons" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_order_item_addons_order_item_id" ON "order_item_addons" ("order_item_id");
CREATE INDEX IF NOT EXISTS "ix_order_item_addons_addon_id" ON "order_item_addons" ("addon_id");

-- Batch(es) a sold line came from (FEFO), so a return goes back to the same batch.
CREATE TABLE IF NOT EXISTS "order_item_batches" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
