  "order_item_id"            INTEGER  NOT NULL REFERENCES "order_items"("id") ON DELETE CASCADE,
  "batch_id"                 INTEGER  REFERENCES "stock_batches"("id") ON DELETE SET NULL,
  "qty_milli"                INTEGER  NOT NULL,
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "order_item_batches_updated_at" AFTER UPDATE ON "order_item_batches" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "order_item_batches" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_order_item_batches_business_id" ON "order_item_batches" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_order_item_batches_order_item_id" ON "order_item_batches" ("order_item_id");
CREATE INDEX IF NOT EXISTS "ix_order_item_batches_batch_id" ON "order_item_batches" ("batch_id");

CREATE TABLE IF NOT EXISTS "sale_return_items" (
  "id"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID
  "business_id"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)
  "return_id"                INTEGER  NOT NULL REFERENCES "sale_returns"("id") ON DELETE CASCADE,
  "order_item_id"            INTEGER  REFERENCES "order_items"("id") ON DELETE SET NULL,
  "product_id"               INTEGER  REFERENCES "products"("id") ON DELETE SET NULL,
  "product_name"             TEXT     NOT NULL,  -- max 150 · snapshot
  "unit"                     TEXT     NOT NULL,  -- max 10
  "qty_milli"                INTEGER  NOT NULL,
  "unit_price_minor"         INTEGER  NOT NULL,
  "amount_minor"             INTEGER  NOT NULL,  -- incl. tax, after the bill's discount share
  "restock"                  INTEGER  NOT NULL DEFAULT 1 CHECK ("restock" IN (0, 1)),  -- false = damaged, not back on the shelf
  "created_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME
  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "sale_return_items_updated_at" AFTER UPDATE ON "sale_return_items" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
BEGIN UPDATE "sale_return_items" SET "updated_at" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE "id" = NEW."id"; END;

CREATE INDEX IF NOT EXISTS "ix_sale_return_items_business_id" ON "sale_return_items" ("business_id");
CREATE INDEX IF NOT EXISTS "ix_sale_return_items_return_id" ON "sale_return_items" ("return_id");
CREATE INDEX IF NOT EXISTS "ix_sale_return_items_order_item_id" ON "sale_return_items" ("order_item_id");
CREATE INDEX IF NOT EXISTS "ix_sale_return_items_product_id" ON "sale_return_items" ("product_id");

