  "updated_at"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME
) STRICT;

CREATE TRIGGER IF NOT EXISTS "kitchen_ticket_items_updated_at" AFTER UPDATE ON "kitchen_ticket_items" FOR EACH ROW WHEN NEW."updated_at" = OLD."updated_at"
